<div class="container">
    <h1>簡易記帳</h1>

    <!-- 統計卡片 -->
    <div class="card">
        <div class="summary-total">本月總支出</div>
        <div class="summary-amount" id="totalAmount">NT$ 0</div>
        <div class="category-totals">
            <div class="cat-item">
                <div class="cat-name">餐飲</div>
                <div class="cat-val" id="sumFood">0</div>
            </div>
            <div class="cat-item">
                <div class="cat-name">交通</div>
                <div class="cat-val" id="sumTransport">0</div>
            </div>
            <div class="cat-item">
                <div class="cat-name">娛樂</div>
                <div class="cat-val" id="sumEntertainment">0</div>
            </div>
            <div class="cat-item">
                <div class="cat-name">其他</div>
                <div class="cat-val" id="sumOther">0</div>
            </div>
        </div>
    </div>

    <!-- 輸入表單 -->
    <div class="card">
        <div class="form-group">
            <label>金額</label>
            <input type="number" id="amountInput" placeholder="請輸入金額" inputmode="numeric">
        </div>
        <div class="form-group">
            <label>分類</label>
            <div class="categories-select">
                <button type="button" class="cat-btn active" data-category="餐飲">餐飲</button>
                <button type="button" class="cat-btn" data-category="交通">交通</button>
                <button type="button" class="cat-btn" data-category="娛樂">娛樂</button>
                <button type="button" class="cat-btn" data-category="其他">其他</button>
            </div>
        </div>
        <div class="form-group">
            <label>備註 (選填)</label>
            <input type="text" id="noteInput" placeholder="例如：午餐、捷運">
        </div>
        <button type="button" class="submit-btn" id="addBtn">新增紀錄</button>
    </div>

    <!-- 紀錄列表 -->
    <div>
        <div class="section-title">
            <span>本月紀錄</span>
        </div>
        <div class="record-list" id="recordList">
            <div class="empty-tip">目前沒有紀錄</div>
        </div>
    </div>
</div>

<script>
    let selectedCategory = '餐飲';
    let records = JSON.parse(localStorage.getItem('simple_accounts')) || [];

    const catButtons = document.querySelectorAll('.cat-btn');
    const amountInput = document.getElementById('amountInput');
    const noteInput = document.getElementById('noteInput');
    const addBtn = document.getElementById('addBtn');
    const recordList = document.getElementById('recordList');

    const totalAmountEl = document.getElementById('totalAmount');
    const sumFoodEl = document.getElementById('sumFood');
    const sumTransportEl = document.getElementById('sumTransport');
    const sumEntertainmentEl = document.getElementById('sumEntertainment');
    const sumOtherEl = document.getElementById('sumOther');

    // 分類按鈕點擊切換
    catButtons.forEach(btn => {
        btn.addEventListener('click', () => {
            catButtons.forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            selectedCategory = btn.getAttribute('data-category');
        });
    });

    // 新增按鈕
    addBtn.addEventListener('click', () => {
        const amountVal = amountInput.value.trim();
        if (!amountVal || Number(amountVal) <= 0) {
            alert('請輸入正確金額');
            return;
        }

        const newRecord = {
            id: Date.now(),
            amount: Number(amountVal),
            category: selectedCategory,
            note: noteInput.value.trim() || selectedCategory,
            date: new Date().toISOString()
        };

        records.unshift(newRecord);
        saveAndRender();

        // 清空輸入
        amountInput.value = '';
        noteInput.value = '';
    });

    // 刪除紀錄
    window.deleteRecord = function(id) {
        records = records.filter(item => item.id !== id);
        saveAndRender();
    };

    function saveAndRender() {
        localStorage.setItem('simple_accounts', JSON.stringify(records));
        render();
    }

    function render() {
        const now = new Date();
        const currentYear = now.getFullYear();
        const currentMonth = now.getMonth();

        // 過濾出本月的紀錄
        const currentMonthRecords = records.filter(item => {
            const itemDate = new Date(item.date);
            return itemDate.getFullYear() === currentYear && itemDate.getMonth() === currentMonth;
        });

        // 計算總計與分類合計
        let total = 0;
        let sums = { '餐飲': 0, '交通': 0, '娛樂': 0, '其他': 0 };

        currentMonthRecords.forEach(item => {
            total += item.amount;
            if (sums[item.category] !== undefined) {
                sums[item.category] += item.amount;
            }
        });

        totalAmountEl.textContent = `NT$ ${total.toLocaleString()}`;
        sumFoodEl.textContent = sums['餐飲'].toLocaleString();
        sumTransportEl.textContent = sums['交通'].toLocaleString();
        sumEntertainmentEl.textContent = sums['娛樂'].toLocaleString();
        sumOtherEl.textContent = sums['其他'].toLocaleString();

        // 渲染列表
        if (currentMonthRecords.length === 0) {
            recordList.innerHTML = '<div class="empty-tip">本月尚無記帳紀錄</div>';
            return;
        }

        let html = '';
        currentMonthRecords.forEach(item => {
            const d = new Date(item.date);
            const dateStr = `${d.getMonth() + 1}/${d.getDate()} ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;

            html += `
                <div class="record-item">
                    <div class="record-info">
                        <div class="record-desc">${escapeHtml(item.note)}</div>
                        <div class="record-meta">${dateStr} · ${item.category}</div>
                    </div>
                    <div class="record-right">
                        <div class="record-amount">-$${item.amount.toLocaleString()}</div>
                        <button class="delete-btn" onclick="deleteRecord(${item.id})">刪</button>
                    </div>
                </div>
            `;
        });
        recordList.innerHTML = html;
    }

    function escapeHtml(text) {
        return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#039;");
    }

    // 初次載入渲染
    render();
</script>

</body>
</html>
